api -i -H If-None-Match: "8f78b22db98f3ef0" repos/o/r/pulls/8
api -i -H If-None-Match: "af398de162b5418b" repos/o/r
api -i -H If-None-Match: "4f53cda18c2baa0c" repos/o/r/issues/8/comments?per_page=100
api -i -H If-None-Match: "4f53cda18c2baa0c" repos/o/r/commits/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa/statuses?per_page=100
api -i -H If-None-Match: "4f53cda18c2baa0c" repos/o/r/pulls/8/comments?per_page=100
api -i -H If-None-Match: "c54cf81d9081f326" repos/o/r/commits/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa/check-runs?filter=all&per_page=100
api -i -H If-None-Match: "4f53cda18c2baa0c" repos/o/r/pulls/8/reviews?per_page=100
pr view https://github.com/o/r/pull/8 --json headRefOid,reviewDecision
pr view https://github.com/o/r/pull/8 --json state -q .state
api graphql --paginate -f owner=o -f repo=r -F number=8 -f query=query($owner: String!, $repo: String!, $number: Int!, $endCursor: String) {
  repository(owner: $owner, name: $repo) {
    pullRequest(number: $number) {
      labels(first: 100) { nodes { name } }
      timelineItems(first: 100, after: $endCursor, itemTypes: [LABELED_EVENT, UNLABELED_EVENT]) {
        pageInfo { hasNextPage endCursor }
        nodes {
          __typename
          ... on LabeledEvent { createdAt label { name } }
          ... on UnlabeledEvent { createdAt label { name } }
        }
      }
    }
  }
} --jq .data.repository.pullRequest as $pr
| if $pr == null then error("no pull request") else
  "present=\($pr.labels.nodes // [] | map(.name) | index("conflict") != null)",
  ($pr.timelineItems.nodes[]?
    | select(.label.name == "conflict")
    | if .__typename == "LabeledEvent" then "labeled_at=\(.createdAt)"
      elif .__typename == "UnlabeledEvent" then "unlabeled_at=\(.createdAt)"
      else empty end)
  end
